from pathlib import Path
import json,html,base64,sys
import pandas as pd,numpy as np
from PIL import Image,ImageDraw
from io import BytesIO
A=Path(__file__).resolve().parent;R=A/'results';name=sys.argv[1] if len(sys.argv)>1 else 'combined_conditional_guard_0.15'
metrics=pd.DataFrame([json.loads(p.read_text()) for p in R.glob('*.json') if 'experiment' in json.loads(p.read_text())]);metrics.sort_values('pooled_ap',ascending=False).to_csv(A/'all_experiment_metrics.csv',index=False)
d=pd.read_csv(R/f'{name}_test_review.csv');d['rank_before']=d.score.rank(method='min',ascending=False).astype(int);d['rank_after']=d.new_score.rank(method='min',ascending=False).astype(int);d.to_csv(A/'selected_test_audit.csv',index=False)
bad=(d.visual_status.isin(['clear_error','likely_error'])&(d.delta<-.02));good=(d.visual_status.eq('plausible_correct')&(d.delta>.02));d[bad|good].to_csv(A/'regression_review.csv',index=False)
flags=d.diagnostic_flag.fillna('').ne('')|d.issue.eq('person_torso_only')|d.issue.str.contains('duplicate')|(d.delta.abs()>=.1)
selected=d[flags].sort_values('review_no');cards=[]
for r in selected.itertuples():
 im=Image.open(A.parent/'rascar_test_visual_audit/images'/f'{r.frame_id}.jpg').convert('RGB');b=np.array([r.x1,r.y1,r.x2,r.y2]);margin=np.maximum((b[2:]-b[:2])*.35,35);roi=b+np.r_[-margin,margin];roi[[0,2]]=np.clip(roi[[0,2]],0,1280);roi[[1,3]]=np.clip(roi[[1,3]],0,720)
 crop=im.crop(tuple(roi));scale=min(440/crop.width,340/crop.height);crop=crop.resize((round(crop.width*scale),round(crop.height*scale)));draw=ImageDraw.Draw(crop);draw.rectangle(tuple((b-np.tile(roi[:2],2))*scale),outline='red',width=2);buf=BytesIO();crop.save(buf,format='JPEG',quality=90);uri='data:image/jpeg;base64,'+base64.b64encode(buf.getvalue()).decode()
 cards.append(f'<article data-class="{r.class_name}" data-status="{r.visual_status}"><h3>#{r.review_no} {r.class_name}</h3><img src="{uri}" alt="Query {r.review_no}"><p><strong>{r.score:.3f} → {r.new_score:.3f}</strong> · rank {r.rank_before} → {r.rank_after}</p><p>{html.escape(r.issue)} · {r.visual_status}</p><p>{html.escape(r.note)}</p><small>{r.id}<br>{r.frame_id}</small></article>')
table=metrics[['experiment','pooled_ap','day_25','day_26','ap_person','ap_nude_hands','test_visual_diagnostic_ap_NOT_validation']].sort_values('pooled_ap',ascending=False).to_html(index=False,float_format=lambda v:f'{v:.6f}',border=0)
text=f'''<!doctype html><meta charset="utf-8"><title>RASCAR V15 — результаты</title><style>body{{font:16px system-ui;margin:30px;background:#f4f6fa;color:#182230}}h1{{font-size:28px}}.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:16px}}article{{background:white;border-radius:12px;padding:16px}}article img{{max-width:100%;height:340px;object-fit:contain}}td,th{{padding:8px;text-align:left;border-bottom:1px solid #dde}}.table{{overflow:auto}}small{{color:#567}}select{{padding:10px;margin:15px 12px 15px 0}}.notice{{background:#fff3cf;padding:18px;border-radius:10px}}</style>
<h1>RASCAR V15: {html.escape(name)}</h1><p class="notice">Валидация: 25→26 и 26→25, 198 боксов / 35 кадров, AP(error, score). Тестовый визуальный аудит — субъективная диагностическая проверка, не скрытая разметка и не оценка LB. Он уже используется при разработке. Строки теста не использованы для обучения. Лучший подтверждённый LB V8: 0.90481; LB новых вариантов неизвестен.</p>
<h2>Все эксперименты</h2><div class="table">{table}</div><h2>Проблемные кадры и изменения</h2><p>Больше score — выше приоритет рамки как ошибки. Координаты входных боксов не меняются. Здесь {len(selected)} диагностических примеров; все 362 строки сохранены в selected_test_audit.csv.</p><select id="cls"><option value="">Все классы</option><option>person</option><option>nude_hands</option><option>cup</option><option>tray</option></select><select id="status"><option value="">Все статусы аудита</option><option>clear_error</option><option>likely_error</option><option>plausible_correct</option><option>uncertain</option></select><div class="cards">{''.join(cards)}</div><script>const cs=document.getElementById('cls'),ss=document.getElementById('status');for(const s of document.querySelectorAll('select'))s.onchange=()=>{{for(const c of document.querySelectorAll('article'))c.hidden=(cs.value&&cs.value!==c.dataset.class)||(ss.value&&ss.value!==c.dataset.status);}};</script>'''
if (A/'SUMMARY.txt').exists():
 text=text.replace('<h2>Все эксперименты</h2>', '<details><summary><strong>Подробные результаты и ограничения</strong></summary><pre style="white-space:pre-wrap;font:15px/1.55 system-ui">'+html.escape((A/'SUMMARY.txt').read_text())+'</pre></details><h2>Все эксперименты</h2>')
(A/'REPORT.html').write_text(text)
print('REPORT_READY',len(metrics),'experiments',len(selected),'visual cases','regressions',int((bad|good).sum()))
